ValidationRule.errorConditionFormula:
AND( $Profile.Name <> 'System Administrator', TEXT(Type) = 'Complaint',
OR ( AND ( TEXT(Nature_Config__c) <> 'Courier Delivery', TEXT(Nature_Config__c) <> 'Policy Retur', TEXT(Nature_Config__c) <> 'Policy Duplicate', TEXT(Nature_Config__c) <> 'Courier Investigation', Entity__c = 'AMFS', $Profile.Name = 'Other Dept AMFS' ) , Entity__c <> 'AMFS'
) , $Profile.Name <> 'CMU-ALI', $Profile.Name <> 'CMU-AFI', $Profile.Name <> 'CMU A-AMFS', $Profile.Name <> 'CMU B-AMFS', $Profile.Name <> 'CMU C-AMFS', $Profile.Name <> 'CMU D-AMFS', $Profile.Name <> 'CMU-MAGI', $Profile.Name <> 'SPV CMU-AFI', $Profile.Name <> 'SPV CMU-AMFS', $Profile.Name <> 'SPV CMU-MAGI', $Profile.Name <> 'Inbound & Outbound Agent AGI', $Profile.Name <> 'Back Office AGI', $Profile.Name <> 'CCC Manager AGI', $Profile.Name <> 'Supervisor Inbound & Outbound AGI', OR( ISCHANGED( Pending_Status__c ), ISCHANGED( Financial_Lost__c ), ISCHANGED( Financial_Lost_Currency__c ), ISCHANGED( Complaint__c ), ISCHANGED( Complaint_Resume__c ), ISCHANGED( Reason_Root_Cause__c ), ISCHANGED( Jenis_Pertanggungan__c ), ISCHANGED( Tanggal_Assign__c ), ISCHANGED( Chronological__c ), ISCHANGED( Demand__c ), ISCHANGED( Subject ), ISCHANGED( Status ), ISCHANGED( Region__c ), ISCHANGED( Other_Information__c ), ISCHANGED( Recommendation__c ), ISCHANGED( Appeal__c ), ISCHANGED( Related_ticket__c ), ISCHANGED( Case_Error__c ), ISCHANGED( Lokasi_Survey__c ), ISCHANGED( PIC_Surveyor__c ), ISCHANGED( COB__c ), ISCHANGED( Received_Party__c ), ISCHANGED( Lampiran__c )))
